class Account {
private:
    int balance = 0;        // спрятано: снаружи не достать

public:
    bool deposit(int sum) { // открытый метод
        if (sum <= 0 || sum > std::numeric_limits<int>::max() - balance)
            return false;
        balance += sum;
        return true;
    }
    int getBalance() const {
        return balance;
    }
};

