#include <iostream>
#include <stdexcept>
class Quota {
    int limit_;
    int used_ = 0;
public:
    explicit Quota(int limit) : limit_(limit) {
        if (limit < 0) throw std::invalid_argument("negative limit");
    }
    bool reserve(int count) {
        if (count <= 0 || count > limit_ - used_) return false;
        used_ += count;
        return true;
    }
    bool release(int count) {
        if (count <= 0 || count > used_) return false;
        used_ -= count;
        return true;
    }
    int remaining() const { return limit_ - used_; }
};
int main() {
    Quota quota{10};
    std::cout << quota.reserve(4) << ' ';
    std::cout << quota.reserve(7) << ' ';
    quota.release(1);
    Quota copy = quota;
    copy.reserve(2);
    std::cout << quota.remaining() << ' ' << copy.remaining(); // 1 0 7 5
}

