#include <iostream>

class Clock {
    int hours_ = 0;
    int minutes_ = 0;
    int seconds_ = 0;
public:
    Clock() = default;

    bool try_set(int h, int m, int s) {
        if (h < 0 || h >= 24 ||
            m < 0 || m >= 60 ||
            s < 0 || s >= 60) {
            return false;
        }
        hours_ = h;
        minutes_ = m;
        seconds_ = s;
        return true;
    }

    void tick() {
        ++seconds_;
        if (seconds_ < 60) return;
        seconds_ = 0;
        ++minutes_;
        if (minutes_ < 60) return;
        minutes_ = 0;
        ++hours_;
        if (hours_ == 24) hours_ = 0;
    }

    int hours() const { return hours_; }
    int minutes() const { return minutes_; }
    int seconds() const { return seconds_; }
};

void print(const char* label, const Clock& clock) {
    std::cout << label << clock.hours() << ':'
              << clock.minutes() << ':' << clock.seconds() << '\n';
}

int main() {
    std::cout << std::boolalpha;
    Clock clock;
    print("start: ", clock);
    std::cout << "set: " << clock.try_set(23, 59, 58) << '\n';
    Clock copy = clock;
    clock.tick();
    print("original: ", clock);
    print("copy: ", copy);
    clock.tick();
    print("midnight: ", clock);
    std::cout << "bad set: " << clock.try_set(12, 80, 10) << '\n';
    print("after refusal: ", clock);
    copy.tick();
    print("copy after tick: ", copy);
    copy = clock;
    print("copy after assignment: ", copy);
}

bool try_set(int h, int m, int s) {
    if (h < 0 || h >= 24) return false;
    hours_ = h; // уже изменили объект
    if (m < 0 || m >= 60) return false;
    minutes_ = m;
    if (s < 0 || s >= 60) return false;
    seconds_ = s;
    return true;
}

